const items = $('When Executed by Another Workflow').all();

// Pull once, not inside the loop
const invoiceDateRaw = $('Check Invoice Exists').first().json.invoice.invoice_date;

// Format YYYY-MM-DD
const invoiceDate = new Date(invoiceDateRaw).toISOString().split('T')[0];

for (const item of items) {
  item.json.InvoiceNumber = true;
  item.json.Invoicedate = invoiceDate;
  item.json.TrueCLinicAbb = $('Get row(s)').first().json.Abb;
}

return items;

